mapper.data:
{
  "model": "anthropic/claude-sonnet-4-6",
  "messages": [
    {
      "role": "user",
      "content": "Write a warm renewal offer email for {{4.client_name}} who is on the {{4.tier}} plan at ${{4.monthly_fee}}/mo. Their annual renewal is in 30 days. Offer: pay for 10 months and get 12 + setup fee waived (saves them ${{6.savings}}). Annual price is ${{6.annual_price}}. Mention their results have been great. 3 short paragraphs. Return only the email body."
    }
  ],
  "max_tokens": 500,
  "temperature": 0.7
}

{
  "from": "Brian at CWI AI <{{env.CWI_ALERT_FROM_ADDRESS}}>",
  "to": ["{{4.client_email}}"],
  "subject": "Your renewal is coming up — here is a special offer",
  "html": "<p>{{replace(7.data.choices[0].message.content; '\n'; '<br>')}}</p><p style='margin-top:24px;padding:16px;background:#f0fdf4;border-left:4px solid #16a34a;font-family:Arial,sans-serif;'><strong>Annual Plan Offer:</strong> Lock in 12 months of service for just <strong>${{6.annual_price}}</strong> — pay for 10 months and get 12, plus your setup fee is waived. That is <strong>${{6.savings}}</strong> back in your pocket.</p>"
}

{
  "from": "{{env.CWI_ALERT_FROM_ADDRESS}}",
  "to": ["{{env.ADMIN_EMAIL}}"],
  "subject": "Renewal email sent to {{4.client_name}} — renewal in 30 days — {{4.tier}} at ${{4.monthly_fee}}/mo",
  "html": "<h2 style='color:#1d4ed8;'>Renewal Reminder Alert</h2><p>A renewal offer email was just sent to a client whose annual contract renews in 30 days.</p><table style='border-collapse:collapse;font-family:Arial,sans-serif;font-size:14px;'><tr><td style='padding:6px 12px;font-weight:bold;'>Client</td><td style='padding:6px 12px;'>{{4.client_name}}</td></tr><tr style='background:#f3f4f6;'><td style='padding:6px 12px;font-weight:bold;'>Email</td><td style='padding:6px 12px;'>{{4.client_email}}</td></tr><tr><td style='padding:6px 12px;font-weight:bold;'>Plan</td><td style='padding:6px 12px;'>{{4.tier}} — ${{4.monthly_fee}}/mo</td></tr><tr style='background:#f3f4f6;'><td style='padding:6px 12px;font-weight:bold;'>Renewal Date</td><td style='padding:6px 12px;'>{{4.renewal_date}} (30 days away)</td></tr><tr><td style='padding:6px 12px;font-weight:bold;'>Annual Offer Price</td><td style='padding:6px 12px;'>${{6.annual_price}} (10 months for 12)</td></tr><tr style='background:#f3f4f6;'><td style='padding:6px 12px;font-weight:bold;'>Client Savings</td><td style='padding:6px 12px;'>${{6.savings}}</td></tr><tr><td style='padding:6px 12px;font-weight:bold;'>Email Sent</td><td style='padding:6px 12px;'>{{4.run_date}} at 9:30 AM ET</td></tr></table><p>Follow up if you do not hear back within 5 business days.</p>"
}

{
  "from": "{{env.CWI_ALERT_FROM_ADDRESS}}",
  "to": ["{{env.ADMIN_EMAIL}}"],
  "subject": "[ERROR] Scenario S Renewal Reminder Failed — {{4.client_name}}",
  "html": "<h2 style='color:#dc2626;'>Scenario S Error</h2><p>The Annual Contract Renewal Reminder (Scenario S) encountered an error and did not complete successfully for one or more clients.</p><table style='border-collapse:collapse;font-family:Arial,sans-serif;font-size:14px;'><tr><td style='padding:6px 12px;font-weight:bold;'>Error Message</td><td style='padding:6px 12px;'>{{error.message}}</td></tr><tr style='background:#f3f4f6;'><td style='padding:6px 12px;font-weight:bold;'>Failed Module</td><td style='padding:6px 12px;'>{{error.module}}</td></tr><tr><td style='padding:6px 12px;font-weight:bold;'>Time</td><td style='padding:6px 12px;'>{{formatDate(now; 'MMMM D, YYYY h:mm A'; 'America/New_York')}} ET</td></tr><tr style='background:#f3f4f6;'><td style='padding:6px 12px;font-weight:bold;'>Client Name</td><td style='padding:6px 12px;'>{{4.client_name}}</td></tr><tr><td style='padding:6px 12px;font-weight:bold;'>Client Email</td><td style='padding:6px 12px;'>{{4.client_email}}</td></tr><tr style='background:#f3f4f6;'><td style='padding:6px 12px;font-weight:bold;'>Plan</td><td style='padding:6px 12px;'>{{4.tier}} — ${{4.monthly_fee}}/mo</td></tr><tr><td style='padding:6px 12px;font-weight:bold;'>Renewal Date</td><td style='padding:6px 12px;'>{{4.renewal_date}}</td></tr><tr style='background:#f3f4f6;'><td style='padding:6px 12px;font-weight:bold;'>Days Until Renewal</td><td style='padding:6px 12px;'>{{4.days_until_renewal}}</td></tr></table><p>Please check the Make.com execution log and send the renewal offer to this client manually if needed.</p>"
}
